void
sort_by_score(idxV, scrV)
  int    *idxV, *scrV;
{
  int     sorted, tmp, i;
  do {
    sorted = 1;
    for (i = 0; i < warriors - 1; ++i)
      if (scrV[idxV[i]] < scrV[idxV[i + 1]]) {
        tmp = idxV[i];
        idxV[i] = idxV[i + 1];
        idxV[i + 1] = tmp;
        sorted = 0;
      }
  } while (!sorted);
}

